1	// Package server exposes the frozen public surface of SignalWatch.
2	//
3	// Besides the baseline process health check, the server accepts in-memory
4	// metric samples at /api/v1/metrics. All new responses use JSON. Metric state
5	// is process-local and is lost on restart.
6	package server
7	
8	import (
9		"bytes"
10		"encoding/json"
11		"io"
12		"math"
13		"mime"
14		"net/http"
15		"net/url"
16		"regexp"
17		"sort"
18		"strconv"
19		"strings"
20		"sync"
21		"time"
22	)
23	
24	// Version is the baseline release identifier.
25	const Version = "0.1.0"
26	
27	const metricsPath = "/api/v1/metrics"
28	
29	var identPattern = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_]*$`)
30	
31	type health struct {
32		Status  string `json:"status"`
33		Service string `json:"service"`
34		Version string `json:"version"`
35	}
36	
37	// series is one uniquely identified time series: name + full label set.
38	type series struct {
39		name   string
40		typ    string
41		labels map[string]string
42	
43		// counter/gauge state
44		value float64
45	
46		// histogram state
47		bucketBounds []float64 // strictly increasing, fixed at first write
48		bucketCounts []int64   // cumulative counts per bound, len == len(bucketBounds)
49		count        int64
50		sum          float64
51	
52		// history holds accepted samples in commit order for range queries.
53		// Entries older than the retention window are ignored at query time;
54		// evicting them never touches the cumulative state above.
55		history []historyPoint
56	}
57	
58	type metricStore struct {
59		mu     sync.RWMutex
60		series map[string]*series
61	
62		// alert rules keyed by rule id; guarded by mu so rule replacement and
63		// alert evaluation are atomic with metric commits.
64		rules map[string]*alertRule
65	
66		// silences keyed by silence id; same lock so alert evaluation reads
67		// metrics, rules and silences from one consistent snapshot.
68		silences map[string]*silence
69	
70		// inhibit rules keyed by rule id; same lock so alert evaluation also
71		// reads inhibit rules from the same consistent snapshot.
72		inhibitions map[string]*inhibitRule
73	
74		// notification routes keyed by route id; same lock so the notification
75		// plan reads routes from the same snapshot as alert evaluation.
76		notificationRoutes map[string]*notificationRoute
77	
78		// SLO definitions keyed by SLO id; same lock so status evaluation reads
79		// definitions and counters from one consistent snapshot.
80		slos map[string]*sloDefinition
81	
82		// Log entries keyed by entry id; same lock so log commits and retrieval
83		// read one consistent snapshot. logOrder is the submission-order FIFO
84		// of ids used for eviction; logSeq is the commit sequence that anchors
85		// paginated read snapshots.
86		logs     map[string]*logEntry
87		logOrder []string
88		logSeq   int64
89	
90		// Spans keyed by tenant-unique "trace_id\x00span_id"; same lock so span
91		// commits and trace reads share the logs snapshot they join against.
92		spans map[string]*span
93	
94		// Deterministic ingest sampling policy; same lock so a policy swap is
95		// atomic with respect to the log/span commits it governs.
96		sampling samplingPolicy
97	
98		// Discovery target snapshot; same lock so reloads swap one immutable
99		// snapshot pointer and queries always read a consistent generation.
100		discovery *discoverySnapshot
101	}
102	
103	func newMetricStore() *metricStore {
104		return &metricStore{
105			series:             make(map[string]*series),
106			rules:              make(map[string]*alertRule),
107			silences:           make(map[string]*silence),
108			inhibitions:        make(map[string]*inhibitRule),
109			notificationRoutes: make(map[string]*notificationRoute),
110			slos:               make(map[string]*sloDefinition),
111			logs:               make(map[string]*logEntry),
112			spans:              make(map[string]*span),
113			sampling:           defaultSamplingPolicy(),
114			discovery:          emptyDiscoverySnapshot(),
115		}
116	}
117	
118	// validatedSample is a sample that passed all format and value checks.
119	type validatedSample struct {
120		key     string
121		name    string
122		typ     string
123		labels  map[string]string
124		value   float64
125		buckets []float64 // non-nil for histograms
126		ts      time.Time
127	}
128	
129	// checkAndApply validates the batch against the current state (and against
130	// itself) and then commits it in array order. A false result signals a type or
131	// bucket-boundary conflict; in that case no state is mutated.
132	func (s *metricStore) checkAndApply(batch []validatedSample) bool {
133		s.mu.Lock()
134		defer s.mu.Unlock()
135	
136		// First pass: conflict detection against committed state and earlier
137		// samples in the same batch.
138		resolved := make(map[string]*series, len(batch))
139		for _, sm := range batch {
140			existing, ok := s.series[sm.key]
141			if !ok {
142				if shadow, seen := resolved[sm.key]; seen {
143					existing, ok = shadow, true
144				}
145			}
146			if ok {
147				if existing.typ != sm.typ {
148					return false
149				}
150				if sm.typ == "histogram" && !equalBuckets(existing.bucketBounds, sm.buckets) {
151					return false
152				}
153				resolved[sm.key] = existing
154				continue
155			}
156			resolved[sm.key] = &series{typ: sm.typ, bucketBounds: sm.buckets}
157		}
158	
159		// Second pass: commit in order.
160		for _, sm := range batch {
161			cur, ok := s.series[sm.key]
162			if !ok {
163				cur = &series{
164					name:         sm.name,
165					typ:          sm.typ,
166					labels:       sm.labels,
167					bucketBounds: append([]float64(nil), sm.buckets...),
168				}
169				if sm.typ == "histogram" {
170					cur.bucketCounts = make([]int64, len(sm.buckets))
171				}
172				s.series[sm.key] = cur
173			}
174			switch sm.typ {
175			case "counter":
176				cur.value += sm.value
177			case "gauge":
178				cur.value = sm.value
179			case "histogram":
180				cur.count++
181				cur.sum += sm.value
182				for i, bound := range cur.bucketBounds {
183					if sm.value <= bound {
184						cur.bucketCounts[i]++
185					}
186				}
187			}
188			cur.history = append(cur.history, historyPoint{ts: sm.ts, value: sm.value})
189		}
190		return true
191	}
192	
193	type seriesOutput struct {
194		Name    string            `json:"name"`
195		Type    string            `json:"type"`
196		Labels  map[string]string `json:"labels"`
197		Value   *float64          `json:"value,omitempty"`
198		Count   *int64            `json:"count,omitempty"`
199		Sum     *float64          `json:"sum,omitempty"`
200		Buckets []bucketOutput    `json:"buckets,omitempty"`
201	}
202	
203	type bucketOutput struct {
204		LE    float64 `json:"le"`
205		Count int64   `json:"count"`
206	}
207	
208	// query returns matching series as ready-to-encode outputs. A series matches
209	// when its name equals name exactly and it contains every selector label.
210	func (s *metricStore) query(name string, selector map[string]string) []seriesOutput {
211		s.mu.RLock()
212		defer s.mu.RUnlock()
213	
214		out := make([]seriesOutput, 0)
215		for _, cur := range s.series {
216			if cur.name != name {
217				continue
218			}
219			matched := true
220			for k, v := range selector {
221				got, ok := cur.labels[k]
222				if !ok || got != v {
223					matched = false
224					break
225				}
226			}
227			if !matched {
228				continue
229			}
230			item := seriesOutput{
231				Name:   cur.name,
232				Type:   cur.typ,
233				Labels: copyLabels(cur.labels),
234			}
235			switch cur.typ {
236			case "counter", "gauge":
237				v := cur.value
238				item.Value = &v
239			case "histogram":
240				c, sum := cur.count, cur.sum
241				item.Count = &c
242				item.Sum = &sum
243				item.Buckets = make([]bucketOutput, len(cur.bucketBounds))
244				for i, bound := range cur.bucketBounds {
245					item.Buckets[i] = bucketOutput{LE: bound, Count: cur.bucketCounts[i]}
246				}
247			}
248			out = append(out, item)
249		}
250	
251		sort.Slice(out, func(i, j int) bool {
252			return compareLabels(out[i].Labels, out[j].Labels) < 0
253		})
254		return out
255	}
256	
257	// compareLabels imposes a normalized lexicographic order on full label sets:
258	// keys are sorted, then (key, value) pairs are compared element-wise, and a
259	// shorter pair list sorts first when it is a prefix of a longer one.
260	func compareLabels(a, b map[string]string) int {
261		ka := sortedKeys(a)
262		kb := sortedKeys(b)
263		n := len(ka)
264		if len(kb) < n {
265			n = len(kb)
266		}
267		for i := 0; i < n; i++ {
268			if ka[i] != kb[i] {
269				return strings.Compare(ka[i], kb[i])
270			}
271			if a[ka[i]] != b[kb[i]] {
272				return strings.Compare(a[ka[i]], b[kb[i]])
273			}
274		}
275		switch {
276		case len(ka) < len(kb):
277			return -1
278		case len(ka) > len(kb):
279			return 1
280		default:
281			return 0
282		}
283	}
284	
285	func sortedKeys(m map[string]string) []string {
286		keys := make([]string, 0, len(m))
287		for k := range m {
288			keys = append(keys, k)
289		}
290		sort.Strings(keys)
291		return keys
292	}
293	
294	func copyLabels(in map[string]string) map[string]string {
295		out := make(map[string]string, len(in))
296		for k, v := range in {
297			out[k] = v
298		}
299		return out
300	}
301	
302	// seriesKey builds a collision-free identity from name + unordered labels.
303	// Name and label keys are restricted to [a-zA-Z0-9_] and cannot contain NUL,
304	// so length-prefixed values remove any ambiguity from arbitrary label values.
305	func seriesKey(name string, labels map[string]string) string {
306		var b strings.Builder
307		b.WriteString(name)
308		for _, k := range sortedKeys(labels) {
309			b.WriteByte(0)
310			b.WriteString(k)
311			b.WriteByte(0)
312			v := labels[k]
313			b.WriteString(strconv.Itoa(len(v)))
314			b.WriteByte(0)
315			b.WriteString(v)
316		}
317		return b.String()
318	}
319	
320	func equalBuckets(a, b []float64) bool {
321		if len(a) != len(b) {
322			return false
323		}
324		for i := range a {
325			if a[i] != b[i] {
326				return false
327			}
328		}
329		return true
330	}
331	
332	// Handler returns the HTTP surface served by SignalWatch.
333	func Handler() http.Handler {
334		return newHandler(newTenantRegistry())
335	}
336	
337	func newHandler(registry *tenantRegistry) http.Handler {
338		mux := http.NewServeMux()
339	
340		mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
341			if r.Method != http.MethodGet {
342				w.Header().Set("Allow", http.MethodGet)
343				http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
344				return
345			}
346			w.Header().Set("Content-Type", "application/json; charset=utf-8")
347			_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "signalwatch", Version: Version})
348		})
349	
350		mux.HandleFunc(metricsPath, func(w http.ResponseWriter, r *http.Request) {
351			switch r.Method {
352			case http.MethodGet:
353				handleMetricsGet(w, r)
354			case http.MethodPost:
355				handleMetricsPost(w, r)
356			default:
357				w.Header().Set("Allow", "GET, POST")
358				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
359			}
360		})
361	
362		registerAlertHandlers(mux)
363		registerSilenceHandlers(mux)
364		registerInhibitHandlers(mux)
365		registerNotificationRouteHandlers(mux)
366		registerSLOHandlers(mux)
367		registerQueryHandler(mux)
368		registerMetricRangeHandler(mux)
369		registerQueryRangeHandler(mux)
370		registerLogHandlers(mux)
371		registerSpanHandlers(mux)
372		registerSamplingPolicyHandlers(mux)
373		registerDiscoveryTargetHandlers(mux)
374	
375		return withTenants(mux, registry)
376	}
377	
378	func handleMetricsPost(w http.ResponseWriter, r *http.Request) {
379		// All samples in the request share this single receive instant: it is the
380		// default timestamp and the anchor for the accepted timestamp window.
381		receivedAt := time.Now()
382		store := tenantStore(r)
383		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
384		if err != nil || mediaType != "application/json" {
385			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
386			return
387		}
388	
389		body, err := io.ReadAll(r.Body)
390		if err != nil {
391			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
392			return
393		}
394	
395		batch, code := decodeMetricsBatch(body, receivedAt)
396		if code != "" {
397			writeAPIError(w, code, http.StatusBadRequest)
398			return
399		}
400	
401		if !store.checkAndApply(batch) {
402			writeAPIError(w, "metric_conflict", http.StatusConflict)
403			return
404		}
405	
406		w.Header().Set("Content-Type", "application/json; charset=utf-8")
407		w.WriteHeader(http.StatusAccepted)
408		_ = json.NewEncoder(w).Encode(map[string]int{"accepted": len(batch)})
409	}
410	
411	type metricsEnvelope struct {
412		Samples *[]json.RawMessage `json:"samples"`
413	}
414	
415	type rawSample struct {
416		Name      *string            `json:"name"`
417		Type      *string            `json:"type"`
418		Labels    *map[string]string `json:"labels"`
419		Value     *float64           `json:"value"`
420		Buckets   *[]float64         `json:"buckets"`
421		Timestamp *string            `json:"timestamp"`
422	}
423	
424	// decodeMetricsBatch performs every format and value check, including the
425	// optional per-sample timestamp. It never returns a partially validated
426	// batch. The returned error code is empty on success.
427	func decodeMetricsBatch(body []byte, receivedAt time.Time) ([]validatedSample, string) {
428		var env metricsEnvelope
429		if !strictDecode(body, &env) || env.Samples == nil || len(*env.Samples) == 0 {
430			return nil, "invalid_metrics"
431		}
432	
433		batch := make([]validatedSample, 0, len(*env.Samples))
434		for _, raw := range *env.Samples {
435			var sm rawSample
436			if !strictDecode(raw, &sm) {
437				return nil, "invalid_metrics"
438			}
439			if sm.Name == nil || sm.Type == nil || sm.Labels == nil || sm.Value == nil {
440				return nil, "invalid_metrics"
441			}
442			name, typ := *sm.Name, *sm.Type
443			if !identPattern.MatchString(name) {
444				return nil, "invalid_metrics"
445			}
446			if typ != "counter" && typ != "gauge" && typ != "histogram" {
447				return nil, "invalid_metrics"
448			}
449			labels := *sm.Labels
450			if labels == nil {
451				return nil, "invalid_metrics" // explicit null labels
452			}
453			for k := range labels {
454				if !identPattern.MatchString(k) {
455					return nil, "invalid_metrics"
456				}
457			}
458			value := *sm.Value
459			if math.IsNaN(value) || math.IsInf(value, 0) {
460				return nil, "invalid_metrics" // encoding/json already rejects NaN/Inf tokens
461			}
462			if typ == "counter" && value < 0 {
463				return nil, "invalid_metrics"
464			}
465	
466			var buckets []float64
467			if typ == "histogram" {
468				if sm.Buckets == nil || !validBuckets(*sm.Buckets) {
469					return nil, "invalid_metrics"
470				}
471				buckets = append([]float64(nil), (*sm.Buckets)...)
472			} else if sm.Buckets != nil {
473				return nil, "invalid_metrics" // buckets only valid on histograms
474			}
475	
476			// The timestamp is optional; every sample without one shares the
477			// request's receive instant.
478			ts := receivedAt
479			if sm.Timestamp != nil {
480				parsed, err := time.Parse(time.RFC3339Nano, *sm.Timestamp)
481				if err != nil {
482					return nil, "invalid_metrics"
483				}
484				ts = parsed
485			}
486			if ts.Before(receivedAt.Add(-metricRetention)) || ts.After(receivedAt.Add(maxFutureSkew)) {
487				return nil, "metric_timestamp_out_of_range"
488			}
489	
490			batch = append(batch, validatedSample{
491				key:     seriesKey(name, labels),
492				name:    name,
493				typ:     typ,
494				labels:  copyLabels(labels),
495				value:   value,
496				buckets: buckets,
497				ts:      ts,
498			})
499		}
500		return batch, ""
501	}
502	
503	func validBuckets(buckets []float64) bool {
504		if len(buckets) == 0 {
505			return false
506		}
507		prev := math.Inf(-1)
508		for _, b := range buckets {
509			if math.IsNaN(b) || math.IsInf(b, 0) || b <= prev {
510				return false
511			}
512			prev = b
513		}
514		return true
515	}
516	
517	// strictDecode decodes JSON, rejecting unknown fields, multiple/ trailing
518	// values and non-object payloads for struct targets.
519	func strictDecode(data []byte, target any) bool {
520		dec := json.NewDecoder(bytes.NewReader(data))
521		dec.DisallowUnknownFields()
522		if err := dec.Decode(target); err != nil {
523			return false
524		}
525		var extra json.RawMessage
526		if err := dec.Decode(&extra); err != io.EOF {
527			return false
528		}
529		return true
530	}
531	
532	func handleMetricsGet(w http.ResponseWriter, r *http.Request) {
533		store := tenantStore(r)
534		values, err := url.ParseQuery(r.URL.RawQuery)
535		if err != nil {
536			writeAPIError(w, "invalid_query", http.StatusBadRequest)
537			return
538		}
539	
540		names := values["name"]
541		if len(names) == 0 || !identPattern.MatchString(names[0]) {
542			writeAPIError(w, "invalid_query", http.StatusBadRequest)
543			return
544		}
545	
546		selector := make(map[string]string)
547		for key, vals := range values {
548			if !strings.HasPrefix(key, "label.") {
549				continue
550			}
551			labelKey := strings.TrimPrefix(key, "label.")
552			if !identPattern.MatchString(labelKey) {
553				writeAPIError(w, "invalid_query", http.StatusBadRequest)
554				return
555			}
556			for _, v := range vals[1:] {
557				if v != vals[0] {
558					writeAPIError(w, "invalid_query", http.StatusBadRequest)
559					return
560				}
561			}
562			selector[labelKey] = vals[0]
563		}
564	
565		seriesList := store.query(names[0], selector)
566		w.Header().Set("Content-Type", "application/json; charset=utf-8")
567		_ = json.NewEncoder(w).Encode(map[string]any{"series": seriesList})
568	}
569	
570	func writeAPIError(w http.ResponseWriter, code string, status int) {
571		w.Header().Set("Content-Type", "application/json; charset=utf-8")
572		w.WriteHeader(status)
573		_ = json.NewEncoder(w).Encode(map[string]any{"error": map[string]string{"code": code}})
574	}
575

