255		expectErrorCode(t, rec, http.StatusBadRequest, "invalid_tenant")
256		rec = discoveryRequest(t, h, http.MethodGet, discoveryTargetsPath, "", "", "bad tenant!")
257		expectErrorCode(t, rec, http.StatusBadRequest, "invalid_tenant")
258	
259		// Tenants are isolated: writes under one tenant are invisible to others.
260		if rec := reloadTargets(t, h, "alpha", `{"targets":[{"id":"a","url":"http://h","labels":{},"enabled":true}]}`); rec.Code != http.StatusOK {
261			t.Fatalf("alpha reload = %d", rec.Code)
262		}
263		body := decodeBody(t, getTargets(t, h, "beta", ""))
264		if body["generation"] != float64(0) || len(body["targets"].([]any)) != 0 {
265			t.Fatalf("beta sees alpha state: %v", body)
266		}
267		body = decodeBody(t, getTargets(t, h, "alpha", ""))
268		if body["generation"] != float64(1) || len(body["targets"].([]any)) != 1 {
269			t.Fatalf("alpha snapshot = %v", body)
270		}
271	
272		// A reload under beta does not touch alpha.
273		if rec := reloadTargets(t, h, "beta", `{"targets":[]}`); rec.Code != http.StatusOK {
274			t.Fatalf("beta reload = %d", rec.Code)
275		}
276		body = decodeBody(t, getTargets(t, h, "alpha", ""))
277		if body["generation"] != float64(1) || len(body["targets"].([]any)) != 1 {
278			t.Fatalf("alpha disturbed by beta: %v", body)
279		}
280	}
