1	package server
2	
3	import (
4		"context"
5		"io"
6		"math"
7		"mime"
8		"net/http"
9		"sort"
10		"strconv"
11		"strings"
12		"time"
13	)
14	
15	const (
16		scrapeHTTPTimeout     = 5 * time.Second
17		reservedScrapeLabel   = "target_id"
18		scrapeStatusOK        = "ok"
19		scrapeStatusError     = "error"
20		unsupportedTypeMarker = "__unsupported__"
21	)
22	
23	// scrapeHTTPClient never follows redirects (a 3xx response is therefore
24	// observable as a non-200 status) and bounds every target exchange.
25	var scrapeHTTPClient = &http.Client{
26		Timeout: scrapeHTTPTimeout,
27		CheckRedirect: func(*http.Request, []*http.Request) error {
28			return http.ErrUseLastResponse
29		},
30	}
31	
32	// ---- wire shapes -----------------------------------------------------------
33	
34	type discoveryScrapeEnvelope struct {
35		TargetIDs *[]string `json:"target_ids"`
36	}
37	
38	type scrapeResultJSON struct {
39		ID       string `json:"id"`
40		Status   string `json:"status"`
41		Accepted int    `json:"accepted"`
42		Code     string `json:"code,omitempty"`
43	}
44	
45	// expositionSample is one parsed metric{labels} value line. The type is the
46	// counter/gauge decided by the nearest preceding TYPE declaration.
47	type expositionSample struct {
48		name   string
49		typ    string
50		labels map[string]string
51		value  float64
52	}
53	
54	// ---- HTTP handler ----------------------------------------------------------
55	
56	func handleDiscoveryScrape(w http.ResponseWriter, r *http.Request) {
57		if r.Method != http.MethodPost {
58			w.Header().Set("Allow", http.MethodPost)
59			writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
60			return
61		}
62		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
63		if err != nil || mediaType != "application/json" {
64			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
65			return
66		}
67	
68		body, err := io.ReadAll(r.Body)
69		if err != nil {
70			writeAPIError(w, "invalid_discovery_scrape", http.StatusBadRequest)
71			return
72		}
73	
74		ids, ok := decodeDiscoveryScrapeBody(body)
75		if !ok {
76			writeAPIError(w, "invalid_discovery_scrape", http.StatusBadRequest)
77			return
78		}
79	
80		store := tenantStore(r)
81	
82		// Pin the generation and the full target snapshot once. A concurrent
83		// reload swaps the snapshot pointer but never mutates this one, so the
84		// rest of the request — selection, URLs, labels and the response
85		// generation — observes exactly this configuration.
86		snap := store.discoverySnapshotNow()
87		targets, code := selectScrapeTargets(snap, ids)
88		if code != "" {
89			switch code {
90			case "discovery_target_not_found":
91				writeAPIError(w, code, http.StatusNotFound)
92			case "discovery_target_disabled":
93				writeAPIError(w, code, http.StatusConflict)
94			}
95			return
96		}
97	
98		scrapedAt := time.Now()
99		results := make([]scrapeResultJSON, 0, len(targets))
100		for _, t := range targets {
101			results = append(results, scrapeOneTarget(r.Context(), store, snap.generation, t, scrapedAt))
102		}
103	
104		writeJSON(w, http.StatusOK, map[string]any{
105			"generation": snap.generation,
106			"results":    results,
107		})
108	}
109	
110	// decodeDiscoveryScrapeBody accepts exactly one JSON object whose sole field
111	// target_ids is an array of valid, unique identifiers. An empty array is
112	// legal and means "every enabled target".
113	func decodeDiscoveryScrapeBody(body []byte) ([]string, bool) {
114		var env discoveryScrapeEnvelope
115		if !strictDecode(body, &env) || env.TargetIDs == nil {
116			return nil, false
117		}
118		ids := *env.TargetIDs
119		seen := make(map[string]bool, len(ids))
120		for _, id := range ids {
121			if !identPattern.MatchString(id) || seen[id] {
122				return nil, false
123			}
124			seen[id] = true
125		}
126		sort.Strings(ids)
127		return ids, true
128	}
129	
130	// selectScrapeTargets resolves the pinned snapshot into the targets to
131	// scrape, already in id order. Explicit ids are validated in two passes —
132	// every id must exist before any enabled check — and then collected in id
133	// order. An empty selection means every enabled target of the snapshot.
134	func selectScrapeTargets(snap *discoverySnapshot, ids []string) ([]discoveryTarget, string) {
135		if len(ids) == 0 {
136			out := make([]discoveryTarget, 0)
137			for _, t := range snap.targets {
138				if t.enabled {
139					out = append(out, t)
140				}
141			}
142			return out, ""
143		}
144	
145		byID := make(map[string]discoveryTarget, len(snap.targets))
146		for _, t := range snap.targets {
147			byID[t.id] = t
148		}
149		for _, id := range ids {
150			if _, exists := byID[id]; !exists {
151				return nil, "discovery_target_not_found"
152			}
153		}
154		out := make([]discoveryTarget, 0, len(ids))
155		for _, id := range ids {
156			t := byID[id]
157			if !t.enabled {
158				return nil, "discovery_target_disabled"
159			}
160			out = append(out, t)
161		}
162		return out, ""
163	}
164	
165	// scrapeOneTarget fetches, parses and commits one target. Every failure is
166	// local to the target: it yields an error result without touching any other
167	// target's outcome.
168	func scrapeOneTarget(ctx context.Context, store *metricStore, generation int64, t discoveryTarget, at time.Time) scrapeResultJSON {
169		fail := func(code string) scrapeResultJSON {
170			return scrapeResultJSON{ID: t.id, Status: scrapeStatusError, Accepted: 0, Code: code}
171		}
172	
173		status, payload, reached := fetchScrapeTarget(ctx, t.url)
174		if !reached {
175			return fail("target_unreachable")
176		}
177		if status != http.StatusOK {
178			return fail("target_http_error")
179		}
180	
181		samples, ok := parseExposition(payload)
182		if !ok {
183			return fail("invalid_exposition")
184		}
185	
186		batch := make([]validatedSample, 0, len(samples))
187		for _, sm := range samples {
188			labels, ok := mergeScrapeLabels(t.labels, sm.labels, t.id)
189			if !ok {
190				return fail("label_conflict")
191			}
192			batch = append(batch, validatedSample{
193				key:    seriesKey(sm.name, labels),
194				name:   sm.name,
195				typ:    sm.typ,
196				labels: labels,
197				value:  sm.value,
198				ts:     at,
199			})
200		}
201	
202		if code := store.commitScrape(generation, batch); code != "" {
203			return fail(code)
204		}
205		return scrapeResultJSON{ID: t.id, Status: scrapeStatusOK, Accepted: len(batch)}
206	}
207	
208	// fetchScrapeTarget performs the single GET against a target. reached is
209	// false for any transport-level failure (including the 5s timeout); a
210	// delivered response — whatever its status — reports reached with the body.
211	func fetchScrapeTarget(ctx context.Context, targetURL string) (status int, body []byte, reached bool) {
212		req, err := http.NewRequestWithContext(ctx, http.MethodGet, targetURL, nil)
213		if err != nil {
214			return 0, nil, false
215		}
216		resp, err := scrapeHTTPClient.Do(req)
217		if err != nil {
218			return 0, nil, false
219		}
220		defer resp.Body.Close()
221	
222		// The client's overall 5s timeout bounds the read as well.
223		payload, err := io.ReadAll(resp.Body)
224		if err != nil {
225			return 0, nil, false
226		}
227		return resp.StatusCode, payload, true
228	}
229	
230	// ---- exposition parsing ----------------------------------------------------
231	
232	// parseExposition parses Prometheus text exposition: TYPE comments and
233	// metric{labels} number / metric number sample lines. A sample's type is its
234	// metric name's nearest preceding TYPE declaration and must be counter or
235	// gauge. Duplicate labels, illegal identifiers, non-finite numbers, stray
236	// tokens and malformed lines all reject the whole exposition.
237	func parseExposition(data []byte) ([]expositionSample, bool) {
238		types := make(map[string]string)
239		samples := make([]expositionSample, 0)
240	
241		for _, rawLine := range strings.Split(string(data), "\n") {
242			line := strings.TrimRight(rawLine, "\r")
243			i := skipExpositionSpace(line, 0)
244			if i == len(line) {
245				continue
246			}
247			if line[i] == '#' {
248				if !parseExpositionTypeLine(line, types) {
249					return nil, false
250				}
251				continue
252			}
253	
254			name, j, ok := readExpositionIdent(line, i)
255			if !ok {
256				return nil, false
257			}
258			valueStart := j
259			j = skipExpositionSpace(line, j)
260	
261			labels := map[string]string{}
262			if j < len(line) && line[j] == '{' {
263				labels, j, ok = readExpositionLabels(line, j+1)
264				if !ok {
265					return nil, false
266				}
267				valueStart = j
268				j = skipExpositionSpace(line, j)
269			}
270			// Without a label block the name and value must be separated.
271			if j == valueStart {
272				return nil, false
273			}
274	
275			end := j
276			for end < len(line) && !isExpositionSpace(line[end]) {
277				end++
278			}
279			token := line[j:end]
280			value, err := strconv.ParseFloat(token, 64)
281			if token == "" || err != nil || math.IsNaN(value) || math.IsInf(value, 0) {
282				return nil, false
283			}
284			if skipExpositionSpace(line, end) != len(line) {
285				return nil, false // trailing tokens (e.g. an explicit timestamp)
286			}
287	
288			typ, declared := types[name]
289			if !declared || (typ != "counter" && typ != "gauge") {
290				return nil, false
291			}
292			samples = append(samples, expositionSample{
293				name:   name,
294				typ:    typ,
295				labels: labels,
296				value:  value,
297			})
298		}
299		return samples, true
300	}
301	
302	// parseExpositionTypeLine handles comments. "# TYPE name type" lines declare
303	// a metric's type: counter/gauge are recorded, the other standard
304	// Prometheus types and any unrecognized word are recorded as unsupported so
305	// a later sample of that name fails the type check. HELP lines, free-form
306	// comments and malformed comments carry no samples and are ignored.
307	func parseExpositionTypeLine(line string, types map[string]string) bool {
308		fields := strings.Fields(line)
309		if len(fields) < 2 || fields[1] != "TYPE" {
310			return true
311		}
312		if len(fields) != 4 || !identPattern.MatchString(fields[2]) {
313			return true
314		}
315		switch fields[3] {
316		case "counter", "gauge":
317			types[fields[2]] = fields[3]
318		default:
319			types[fields[2]] = unsupportedTypeMarker
320		}
321		return true
322	}
323	
324	// readExpositionIdent consumes [a-zA-Z_][a-zA-Z0-9_]* at offset i.
325	func readExpositionIdent(line string, i int) (string, int, bool) {
326		start := i
327		for i < len(line) {
328			c := line[i]
329			if c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
330				(i > start && c >= '0' && c <= '9') {
331				i++
332				continue
333			}
334			break
335		}
336		if i == start || !identPattern.MatchString(line[start:i]) {
337			return "", 0, false
338		}
339		return line[start:i], i, true
340	}
341	
342	// readExpositionLabels parses the inside of a {...} label block starting
343	// after the opening brace, returning the labels and the offset just past the
344	// closing brace. Values use the Prometheus escapes \\, \" and \n.
345	func readExpositionLabels(line string, i int) (map[string]string, int, bool) {
346		labels := map[string]string{}
347		for {
348			i = skipExpositionSpace(line, i)
349			if i >= len(line) {
350				return nil, 0, false
351			}
352			if line[i] == '}' {
353				return labels, i + 1, true
354			}
355			key, j, ok := readExpositionIdent(line, i)
356			if !ok {
357				return nil, 0, false
358			}
359			if _, dup := labels[key]; dup {
360				return nil, 0, false
361			}
362			j = skipExpositionSpace(line, j)
363			if j >= len(line) || line[j] != '=' {
364				return nil, 0, false
365			}
366			j = skipExpositionSpace(line, j+1)
367			if j >= len(line) || line[j] != '"' {
368				return nil, 0, false
369			}
370			value, j, ok := readExpositionQuoted(line, j+1)
371			if !ok {
372				return nil, 0, false
373			}
374			labels[key] = value
375			j = skipExpositionSpace(line, j)
376			if j >= len(line) {
377				return nil, 0, false
378			}
379			switch line[j] {
380			case ',':
381				i = j + 1
382			case '}':
383				return labels, j + 1, true
384			default:
385				return nil, 0, false
386			}
387		}
388	}
389	
390	// readExpositionQuoted consumes a double-quoted label value starting after
391	// the opening quote, returning the unescaped value and the offset past the
392	// closing quote.
393	func readExpositionQuoted(line string, i int) (string, int, bool) {
394		var b strings.Builder
395		for i < len(line) {
396			switch c := line[i]; {
397			case c == '"':
398				return b.String(), i + 1, true
399			case c == '\\':
400				if i+1 >= len(line) {
401					return "", 0, false
402				}
403				switch line[i+1] {
404				case '\\':
405					b.WriteByte('\\')
406				case '"':
407					b.WriteByte('"')
408				case 'n':
409					b.WriteByte('\n')
410				default:
411					return "", 0, false
412				}
413				i += 2
414			default:
415				b.WriteByte(c)
416				i++
417			}
418		}
419		return "", 0, false
420	}
421	
422	func skipExpositionSpace(line string, i int) int {
423		for i < len(line) && isExpositionSpace(line[i]) {
424			i++
425		}
426		return i
427	}
428	
429	func isExpositionSpace(c byte) bool {
430		return c == ' ' || c == '\t'
431	}
432	
433	// ---- label merge -----------------------------------------------------------
434	
435	// mergeScrapeLabels combines the target's static labels with one sample's
436	// labels. A key present in both with different values, or use of the
437	// reserved target_id key in either source, is a conflict. Otherwise
438	// target_id=<target id> is added.
439	func mergeScrapeLabels(static, sample map[string]string, targetID string) (map[string]string, bool) {
440		if _, reserved := static[reservedScrapeLabel]; reserved {
441			return nil, false
442		}
443		if _, reserved := sample[reservedScrapeLabel]; reserved {
444			return nil, false
445		}
446		merged := make(map[string]string, len(static)+len(sample)+1)
447		for k, v := range sample {
448			merged[k] = v
449		}
450		for k, v := range static {
451			if existing, ok := merged[k]; ok && existing != v {
452				return nil, false
453			}
454			merged[k] = v
455		}
456		merged[reservedScrapeLabel] = targetID
457		return merged, true
458	}
459	
460	// commitScrape validates and applies one target's scrape batch atomically.
461	// Existing series must keep their type; on conflict nothing — metrics or
462	// baselines — changes. Gauges overwrite the current value. A counter is a
463	// cumulative reading: the first time the series is seen under the pinned
464	// generation the full value is written, later non-decreasing readings add
465	// the delta, and a decrease is treated as a reset (the new full value).
466	func (s *metricStore) commitScrape(generation int64, batch []validatedSample) string {
467		s.mu.Lock()
468		defer s.mu.Unlock()
469	
470		// First pass: detect type conflicts against committed state and earlier
471		// samples of the same series within this batch.
472		resolved := make(map[string]*series, len(batch))
473		for _, sm := range batch {
474			existing, ok := s.series[sm.key]
475			if !ok {
476				if shadow, seen := resolved[sm.key]; seen {
477					existing, ok = shadow, true
478				}
479			}
480			if ok {
481				if existing.typ != sm.typ {
482					return "metric_conflict"
483				}
484				resolved[sm.key] = existing
485				continue
486			}
487			resolved[sm.key] = &series{typ: sm.typ}
488		}
489	
490		baselines, ok := s.scrapeBaselines[generation]
491		if !ok {
492			baselines = make(map[string]float64)
493			s.scrapeBaselines[generation] = baselines
494		}
495	
496		// Second pass: commit in array order.
497		for _, sm := range batch {
498			cur, ok := s.series[sm.key]
499			if !ok {
500				cur = &series{
501					name:   sm.name,
502					typ:    sm.typ,
503					labels: sm.labels,
504				}
505				s.series[sm.key] = cur
506			}
507	
508			var written float64
509			switch sm.typ {
510			case "gauge":
511				written = sm.value
512			case "counter":
513				prev, seen := baselines[sm.key]
514				switch {
515				case !seen:
516					written = sm.value // first reading under this generation
517				case sm.value >= prev:
518					written = sm.value - prev
519				default:
520					written = sm.value // counter reset
521				}
522			}
523			baselines[sm.key] = sm.value
524	
525			switch sm.typ {
526			case "counter":
527				cur.value += written
528			case "gauge":
529				cur.value = written
530			}
531			cur.history = append(cur.history, historyPoint{ts: sm.ts, value: written})
532		}
533		return ""
534	}
